"""Characterization tests generated by Inherit.

Each test pins behavior OBSERVED when the code ran; it records what the code does today,
not what it should do. Review tests marked REVIEW before treating them as correct.
Module state and the environment variables a call read are reset to what was recorded when
it was observed (monkeypatch restores them afterwards), so these tests neither depend on nor
leak into other tests' state.
"""
import copy

import pytest
import cronjob.control
import cronjob.parse

def test_cronjob_control_pause_case_1(monkeypatch):  # evidence: E-0035, E-0036
    monkeypatch.setattr(cronjob.control, 'STATE', {'paused': False, 'draining': False, 'queued': 3})
    assert cronjob.control.pause() == None

def test_cronjob_control_drain_case_1(monkeypatch):  # evidence: E-0037, E-0038
    monkeypatch.setattr(cronjob.control, 'STATE', {'paused': False, 'draining': False, 'queued': 3})
    assert cronjob.control.drain() == None

def test_cronjob_control_status_case_1(monkeypatch):  # evidence: E-0039, E-0040
    monkeypatch.setattr(cronjob.control, 'STATE', {'paused': False, 'draining': False, 'queued': 3})
    assert cronjob.control.status() == 'running'

def test_cronjob_control_can_accept_jobs_case_1(monkeypatch):  # evidence: E-0041, E-0042
    monkeypatch.setattr(cronjob.control, 'STATE', {'paused': False, 'draining': False, 'queued': 3})
    assert cronjob.control.can_accept_jobs() == True

# REVIEW: raises ValueError for these inputs; confirm this is intended
def test_cronjob_parse_parse_interval_case_1():  # evidence: E-0043, E-0044
    with pytest.raises(ValueError) as info:
        cronjob.parse.parse_interval('')
    assert str(info.value) == "invalid literal for int() with base 10: ''"

